wait.fn:
(() => {
  const rows = Array.from(document.querySelectorAll('[data-testid=activity-row]'));
  if (rows.length < 2) return false;
  const latest = rows.slice(0, 2);
  const issueIds = latest.map((row) => row.querySelector('code')?.textContent);
  return latest[0].textContent.includes('claimed') &&
    latest[1].textContent.includes('created') &&
    latest.every((row) => row.textContent.includes('loom-e2e')) &&
    issueIds.every((id) => id && id === issueIds[0]) &&
    latest[0].querySelector('[data-marker]')?.getAttribute('data-marker') === 'op';
})()

(() => {
  const rows = Array.from(document.querySelectorAll('[data-testid=activity-row]'));
  const issueId = rows[0]?.querySelector('code')?.textContent;
  if (!issueId) return false;
  const latest = rows.filter((row) => row.querySelector('code')?.textContent === issueId);
  const occurrences = (text) => latest.filter((row) => row.textContent.includes(text)).length;
  return latest.length >= 2 &&
    latest[0].textContent.includes('set to in progress') &&
    latest[1].textContent.includes('set to open') &&
    occurrences('set to in progress') === 1 &&
    occurrences('set to open') === 1 &&
    latest.every((row) => row.textContent.includes('loom-e2e')) &&
    latest[0].querySelector('[data-marker]')?.getAttribute('data-marker') === 'op';
})()

(() => {
  const panel = document.querySelector('[data-testid=issue-detail-panel]');
  return panel?.getAttribute('data-state') === 'open' &&
    panel?.getAttribute('data-loading') === 'false' &&
    document.querySelector('[data-testid=issue-header]')?.textContent.includes('aft issue detail blocker ${RUN_ID:-local}-${AFT_CASE_ID}');
})()

(() => {
  const panel = document.querySelector('[data-testid=issue-detail-panel]');
  const header = document.querySelector('[data-testid=issue-header]')?.textContent || '';
  return panel?.getAttribute('data-state') === 'open' &&
    panel?.getAttribute('data-loading') === 'false' &&
    header.includes('aft issue detail ${RUN_ID:-local}-${AFT_CASE_ID}') &&
    !header.includes('blocker');
})()

(() => {
  const description = document.querySelector('[data-testid=editable-description]')?.textContent || '';
  return description.includes('Initial issue detail description ${RUN_ID:-local}-${AFT_CASE_ID}.') &&
    !description.includes('discarded draft');
})()
